import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"1.4 用真实任务验收 MVP","description":"让首位用户不依赖开发者也能独立使用。","frontmatter":{"title":"1.4 用真实任务验收 MVP","description":"让首位用户不依赖开发者也能独立使用。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/1-4.md","filePath":"delivery/stage-1/1-4.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-1/1-4.md"};function o(n,e,d,s,c,_){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_1-4-用真实任务验收-mvp" tabindex="-1">1.4 用真实任务验收 MVP <a class="header-anchor" href="#_1-4-用真实任务验收-mvp" aria-label="Permalink to &quot;1.4 用真实任务验收 MVP&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已完成：</strong> 15 个真实任务完成验收，13 个通过；阶段一验收时 <code>npm test</code> 为 40 个测试文件、198 个测试，当前已扩展到 54 个测试文件、296 个测试；<code>npm run typecheck</code> 和 <code>npm run build</code> 通过。</li><li><strong>未完成：</strong> T07 因测试文件未提交而失败，T08 的评论动作待批准；这两项是阶段一之后仍需补齐的边界。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>用真实任务证明 MVP 已经可以日常使用，并让它具备安装、启动、备份和退出的基本能力。完成这个阶段后，首位用户不依赖开发者也能独立使用。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>用 1.1 确定的 15 个真实任务逐项验收，记录成功率、人工时间、失败类型和用户反馈。</li><li>修复最影响使用的三个问题：任务丢失、失败无法恢复、审批或产物看不懂。</li><li>提供简单的安装和启动方式，说明数据保存在哪里、如何备份和导出。</li><li>增加全局停止开关和基础权限设置，让用户随时停下系统。</li><li>让首位用户连续使用一周，收集真实使用中的问题和不愿继续使用的原因。</li><li>只有至少 10 个任务通过验收、失败可恢复、用户愿意继续使用时，MVP 才算完成。</li></ol>',7)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
